    }
}

contracts/CombinedStakingContracts.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

// Define interface for compatibility
interface ILiquidityVault {
    function deposit(uint256 amount) external;
    function withdraw(uint256 amount) external;
    function balanceOf(address user) external view returns (uint256);
}

interface IGovernanceDividendPool {
    function stake(uint256 amount) external;
    function withdraw(uint256 amount) external;
    function claim() external;
}

interface ISWFVaultAdapter {
    function deposit(uint256 amount) external;
    function withdraw(uint256 amount) external;
    function forwardToVault(uint256 amount) external;
}

/* ============================
   Module 1: LiquidityVault.sol
   ============================ */
contract LiquidityVault is Ownable {
    IERC20 public lpToken;
    mapping(address => uint256) public staked;
    uint256 public totalStaked;

    constructor(address _lpToken) Ownable(msg.sender) {
        lpToken = IERC20(_lpToken);
    }

    function deposit(uint256 amount) external {
        require(amount > 0, "Zero amount");
        lpToken.transferFrom(msg.sender, address(this), amount);
        staked[msg.sender] += amount;
        totalStaked += amount;
    }

    function withdraw(uint256 amount) external {
        require(staked[msg.sender] >= amount, "Insufficient");
        staked[msg.sender] -= amount;
        totalStaked -= amount;
        lpToken.transfer(msg.sender, amount);
    }

    function balanceOf(address user) public view returns (uint256) {
        return staked[user];
    }
}

/* ============================================
   Module 2: GovernanceDividendPool.sol
   ============================================ */
contract GovernanceDividendPool is Ownable {
    IERC20 public swfToken;
    mapping(address => uint256) public stakes;
    uint256 public totalStaked;
    mapping(address => uint256) public lastClaim;
    uint256 public rewardRate;

    constructor(address _swfToken, uint256 _rate) Ownable(msg.sender) {
        swfToken = IERC20(_swfToken);
        rewardRate = _rate;
    }

    function stake(uint256 amount) external {
        require(amount > 0, "Zero amount");
        swfToken.transferFrom(msg.sender, address(this), amount);
        stakes[msg.sender] += amount;
        totalStaked += amount;
        lastClaim[msg.sender] = block.timestamp;
    }

    function withdraw(uint256 amount) external {
        require(stakes[msg.sender] >= amount, "Insufficient stake");
        claim();
        stakes[msg.sender] -= amount;
        totalStaked -= amount;
        swfToken.transfer(msg.sender, amount);
    }

    function claim() public {
        uint256 time = block.timestamp - lastClaim[msg.sender];
        uint256 reward = (stakes[msg.sender] * rewardRate * time) / 30 days / 1e18;
        lastClaim[msg.sender] = block.timestamp;
        payable(msg.sender).transfer(reward);
    }

    receive() external payable {}
}

/* =======================================
   Module 3: SWFVaultAdapter.sol
   ======================================= */
contract SWFVaultAdapter is Ownable {
    IERC20 public swf;
    address public vault;

    mapping(address => uint256) public deposits;
    uint256 public totalDeposits;

    constructor(address _swf, address _vault) Ownable(msg.sender) {
        swf = IERC20(_swf);
        vault = _vault;
    }

    function deposit(uint256 amount) external {
        require(amount > 0, "Zero deposit");
        swf.transferFrom(msg.sender, address(this), amount);
        deposits[msg.sender] += amount;
        totalDeposits += amount;
    }

    function withdraw(uint256 amount) external {
        require(deposits[msg.sender] >= amount, "Insufficient");
        deposits[msg.sender] -= amount;
        totalDeposits -= amount;
        swf.transfer(msg.sender, amount);
    }

    function forwardToVault(uint256 amount) external onlyOwner {
        swf.transfer(vault, amount);
    }
}

contracts/DynamicAPRController.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "./SWFBasketVault.sol";
import "./SoloMethodEngineV2.sol";

/**
 * @title DynamicAPRController
 * @notice Contract that dynamically adjusts the APR of staking contracts based on the vault deposits
 * @dev This contract monitors the SWFBasketVault deposits and adjusts the SoloMethodEngine APR accordingly
 */
contract DynamicAPRController is Ownable {
    // Address of the SWFBasketVault contract
    SWFBasketVault public basketVault;

    // Address of the staking contract (SoloMethodEngine)
    address public stakingContract;

    // Interface to the staking contract for proper type checking
    SoloMethodEngineV2 public stakingContractInterface;

    // APR levels based on total deposits (in basis points, 1% = 100 basis points)
    uint256 public minAPR = 1000;      // 10% minimum APR
    uint256 public maxAPR = 3000;      // 30% maximum APR

    // Deposit thresholds for APR adjustment (in tokens)
    uint256 public lowDepositThreshold = 10000 ether;     // 10,000 tokens
    uint256 public highDepositThreshold = 100000 ether;   // 100,000 tokens

    // Interval for APR adjustments (in seconds)
    uint256 public adjustmentInterval = 1 days;

    // Timestamp of the last APR adjustment
    uint256 public lastAdjustmentTime;

    // Current APR (in basis points)
    uint256 public currentAPR;

    // Events
    event APRAdjusted(uint256 oldAPR, uint256 newAPR);
    event ThresholdsUpdated(uint256 lowThreshold, uint256 highThreshold);
    event APRRangeUpdated(uint256 minAPR, uint256 maxAPR);
    event AdjustmentIntervalUpdated(uint256 interval);
    event StakingContractUpdated(address oldContract, address newContract);
    event BasketVaultUpdated(address oldVault, address newVault);

    /**
     * @notice Initializes the DynamicAPRController contract
     * @param _basketVault Address of the SWFBasketVault contract
     * @param _stakingContract Address of the staking contract (SoloMethodEngine)
     * @param _initialAPR Initial APR value (in basis points)
     * @param initialOwner Address of the initial owner
     */
    constructor(
        address _basketVault,
        address _stakingContract,
        uint256 _initialAPR,
        address initialOwner
    ) Ownable(initialOwner) {
        require(_basketVault != address(0), "Invalid vault address");
        require(_stakingContract != address(0), "Invalid staking contract address");
        require(_initialAPR >= minAPR && _initialAPR <= maxAPR, "Invalid initial APR");

        basketVault = SWFBasketVault(_basketVault);
        stakingContract = _stakingContract;
        stakingContractInterface = SoloMethodEngineV2(_stakingContract);
        currentAPR = _initialAPR;
        lastAdjustmentTime = block.timestamp;
    }

    /**
     * @notice Adjusts the APR based on the current vault deposits
     * @dev This function calculates the appropriate APR based on the deposit thresholds
     *      and sets it in the staking contract. Can only be called after the adjustment interval has passed.
     */
    function adjustAPR() external {
        require(block.timestamp >= lastAdjustmentTime + adjustmentInterval, "Adjustment interval not reached");

        uint256 totalDeposited = basketVault.totalDeposited();
        uint256 newAPR;

        if (totalDeposited <= lowDepositThreshold) {
            // Below low threshold - set to maximum APR
            newAPR = maxAPR;
        } else if (totalDeposited >= highDepositThreshold) {
            // Above high threshold - set to minimum APR
            newAPR = minAPR;
        } else {
            // Linear interpolation between min and max APR
            uint256 range = maxAPR - minAPR;
            uint256 depositRange = highDepositThreshold - lowDepositThreshold;
            uint256 depositAboveLow = totalDeposited - lowDepositThreshold;

            // Calculate how far we are in the deposit range (0-1)
            uint256 position = (depositAboveLow * 1e18) / depositRange;

            // Calculate APR (inverted - higher deposits = lower APR)
            newAPR = maxAPR - (position * range / 1e18);
        }

        uint256 oldAPR = currentAPR;
        currentAPR = newAPR;
        lastAdjustmentTime = block.timestamp;

        // Call setAPR on the staking contract using the proper interface
        // Note: This controller must have APR_MANAGER_ROLE on the staking contract
        try stakingContractInterface.setAPR(newAPR) {
            // Success - APR was set
        } catch Error(string memory reason) {
            revert(string(abi.encodePacked("Failed to adjust APR: ", reason)));
        } catch {
            revert("Failed to adjust APR on staking contract");
        }

        emit APRAdjusted(oldAPR, newAPR);
    }

    /**
     * @notice Updates the deposit thresholds for APR adjustment
     * @param _lowThreshold New low deposit threshold (in tokens)
     * @param _highThreshold New high deposit threshold (in tokens)
     */
    function updateThresholds(uint256 _lowThreshold, uint256 _highThreshold) external onlyOwner {
        require(_lowThreshold < _highThreshold, "Low threshold must be less than high threshold");

        lowDepositThreshold = _lowThreshold;
        highDepositThreshold = _highThreshold;

        emit ThresholdsUpdated(_lowThreshold, _highThreshold);
    }

    /**
     * @notice Updates the APR range
     * @param _minAPR New minimum APR (in basis points)
     * @param _maxAPR New maximum APR (in basis points)
     */
    function updateAPRRange(uint256 _minAPR, uint256 _maxAPR) external onlyOwner {
        require(_minAPR < _maxAPR, "Min APR must be less than max APR");
        require(_maxAPR <= 5000, "Max APR cannot exceed 50%");

        minAPR = _minAPR;
        maxAPR = _maxAPR;

        emit APRRangeUpdated(_minAPR, _maxAPR);
    }

    /**
     * @notice Updates the adjustment interval
     * @param _interval New adjustment interval (in seconds)
     */
    function updateAdjustmentInterval(uint256 _interval) external onlyOwner {
        require(_interval >= 1 hours, "Interval too short");
        require(_interval <= 30 days, "Interval too long");

        adjustmentInterval = _interval;

        emit AdjustmentIntervalUpdated(_interval);
    }

    /**
     * @notice Updates the staking contract address
     * @param _stakingContract New staking contract address
     */
    function updateStakingContract(address _stakingContract) external onlyOwner {
        require(_stakingContract != address(0), "Invalid staking contract address");

        address oldContract = stakingContract;
        stakingContract = _stakingContract;
        stakingContractInterface = SoloMethodEngineV2(_stakingContract);

        emit StakingContractUpdated(oldContract, _stakingContract);
    }

    /**
     * @notice Updates the basket vault address
     * @param _basketVault New basket vault address
     */
    function updateBasketVault(address _basketVault) external onlyOwner {
        require(_basketVault != address(0), "Invalid vault address");

        address oldVault = address(basketVault);
        basketVault = SWFBasketVault(_basketVault);

        emit BasketVaultUpdated(oldVault, _basketVault);
    }

    /**
     * @notice Calculates what the APR would be given a deposit amount without changing the actual APR
     * @param depositAmount The total deposit amount to simulate
     * @return The APR that would be set for the given deposit amount
     */
    function simulateAPRForDeposit(uint256 depositAmount) external view returns (uint256) {
        if (depositAmount <= lowDepositThreshold) {
            return maxAPR;
        } else if (depositAmount >= highDepositThreshold) {
            return minAPR;
        } else {
            uint256 range = maxAPR - minAPR;
            uint256 depositRange = highDepositThreshold - lowDepositThreshold;
            uint256 depositAboveLow = depositAmount - lowDepositThreshold;

            uint256 position = (depositAboveLow * 1e18) / depositRange;
            return maxAPR - (position * range / 1e18);
        }
    }

    /**
     * @notice Returns the current APR and next adjustment time
     * @return _currentAPR Current APR in basis points
     * @return _nextAdjustmentTime Timestamp when next adjustment is allowed
     * @return _totalDeposited Current total deposits in the vault
     */
    function getAPRInfo() external view returns (uint256 _currentAPR, uint256 _nextAdjustmentTime, uint256 _totalDeposited) {
        return (
            currentAPR,
            lastAdjustmentTime + adjustmentInterval,
            basketVault.totalDeposited()
        );
    }

    /**
     * @notice Check if this controller has permission to set APR on the staking contract
     * @return True if this controller can set APR on the staking contract
     */
    function canSetAPR() external view returns (bool) {
        try stakingContractInterface.isAPRManager(address(this)) returns (bool result) {
            return result;
        } catch {
            return false;
        }
    }

    /**
     * @notice Get the current APR from the staking contract
     * @return Current APR in basis points from the staking contract
     */
    function getStakingContractAPR() external view returns (uint256) {
        try stakingContractInterface.getCurrentAPR() returns (uint256 apr) {
            return apr;
        } catch {
            return 0;
        }
    }

    /**
     * @notice Request APR manager role on the staking contract
     * @dev This should be called after deployment and the staking contract owner should grant the role
     */
    function requestAPRManagerRole() external view returns (bytes32) {
        return stakingContractInterface.getAPRManagerRole();
    }
}

contracts/EnhancedNFTMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";

/**
 * @title Enhanced NFT Marketplace for MetalOfTheGods
 * @dev Advanced marketplace with batch auctions, dynamic fees, and collection-wide features
 */
contract EnhancedNFTMarketplace is ReentrancyGuard, Pausable, AccessControl {
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant MODERATOR_ROLE = keccak256("MODERATOR_ROLE");

    uint256 private _listingIdCounter;
    uint256 private _auctionIdCounter;

    struct Listing {
        uint256 listingId;
        address nftContract;
        uint256 tokenId;
        address seller;
        uint256 price;
        bool active;
        uint256 timestamp;
    }

    struct Auction {
        uint256 auctionId;
        address nftContract;
        uint256 tokenId;
        address seller;
        uint256 startingBid;
        uint256 currentBid;
        address highestBidder;
        uint256 endTime;
        bool active;
        bool isCollection;
        uint256[] tokenIds; // For collection auctions
    }

    struct BatchListing {
        uint256[] tokenIds;
        uint256[] prices;
        address seller;
        bool active;
    }

    // Mappings
    mapping(uint256 => Listing) public listings;
    mapping(uint256 => Auction) public auctions;
    mapping(address => mapping(uint256 => uint256)) public tokenToListing;
    mapping(address => uint256[]) public userListings;
    mapping(address => uint256[]) public userAuctions;
    mapping(uint256 => mapping(address => uint256)) public auctionBids;

    // Fee structure
    uint256 public marketplaceFee = 250; // 2.5%
    uint256 public constant MAX_FEE = 1000; // 10% max
    address public feeRecipient;

    // Trading incentives
    mapping(address => uint256) public tradingVolume;
    mapping(address => uint256) public tradingRewards;
    uint256 public volumeRewardRate = 10; // 0.1% of volume as rewards

    // Events
    event ItemListed(uint256 indexed listingId, address indexed nftContract, uint256 indexed tokenId, address seller, uint256 price);
    event ItemSold(uint256 indexed listingId, address indexed buyer, uint256 price);
    event AuctionCreated(uint256 indexed auctionId, address indexed nftContract, uint256 indexed tokenId, address seller, uint256 startingBid, uint256 endTime);
    event BidPlaced(uint256 indexed auctionId, address indexed bidder, uint256 amount);
    event AuctionEnded(uint256 indexed auctionId, address indexed winner, uint256 finalBid);
    event BatchListed(address indexed seller, uint256[] tokenIds, uint256[] prices);
    event TradingRewardPaid(address indexed trader, uint256 amount);

    constructor(address _feeRecipient) {
        feeRecipient = _feeRecipient;
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    /**
     * @dev List a single NFT for sale
     */
    function listItem(
        address nftContract,
        uint256 tokenId,
        uint256 price
    ) external nonReentrant whenNotPaused {
        require(price > 0, "Price must be greater than zero");
        require(IERC721(nftContract).ownerOf(tokenId) == msg.sender, "Not token owner");
        require(IERC721(nftContract).isApprovedForAll(msg.sender, address(this)), "Contract not approved");

        _listingIdCounter++;
        uint256 listingId = _listingIdCounter;

        listings[listingId] = Listing({
            listingId: listingId,
            nftContract: nftContract,
            tokenId: tokenId,
            seller: msg.sender,
            price: price,
            active: true,
            timestamp: block.timestamp
        });

        tokenToListing[nftContract][tokenId] = listingId;
        userListings[msg.sender].push(listingId);

        emit ItemListed(listingId, nftContract, tokenId, msg.sender, price);
    }

    /**
     * @dev Batch list multiple NFTs
     */
    function batchListItems(
        address nftContract,
        uint256[] calldata tokenIds,
        uint256[] calldata prices
    ) external nonReentrant whenNotPaused {
        require(tokenIds.length == prices.length, "Arrays length mismatch");
        require(tokenIds.length <= 50, "Too many items");

        for (uint256 i = 0; i < tokenIds.length; i++) {
            require(IERC721(nftContract).ownerOf(tokenIds[i]) == msg.sender, "Not owner of all tokens");
            require(prices[i] > 0, "Invalid price");
        }

        require(IERC721(nftContract).isApprovedForAll(msg.sender, address(this)), "Contract not approved");

        for (uint256 i = 0; i < tokenIds.length; i++) {
            _listingIdCounter++;
            uint256 listingId = _listingIdCounter;

            listings[listingId] = Listing({
                listingId: listingId,
                nftContract: nftContract,
                tokenId: tokenIds[i],
                seller: msg.sender,
                price: prices[i],
                active: true,
                timestamp: block.timestamp
            });

            tokenToListing[nftContract][tokenIds[i]] = listingId;
            userListings[msg.sender].push(listingId);

            emit ItemListed(listingId, nftContract, tokenIds[i], msg.sender, prices[i]);
        }

        emit BatchListed(msg.sender, tokenIds, prices);
    }

    /**
     * @dev Buy an NFT
     */
    function buyItem(uint256 listingId) external payable nonReentrant whenNotPaused {
        Listing storage listing = listings[listingId];
        require(listing.active, "Listing not active");
        require(msg.value >= listing.price, "Insufficient payment");

        listing.active = false;

        // Calculate fees
        uint256 fee = (listing.price * marketplaceFee) / 10000;
        uint256 sellerAmount = listing.price - fee;

        // Transfer NFT
        IERC721(listing.nftContract).safeTransferFrom(
            listing.seller,
            msg.sender,
            listing.tokenId
        );

        // Transfer payments
        payable(listing.seller).transfer(sellerAmount);
        payable(feeRecipient).transfer(fee);

        // Handle excess payment
        if (msg.value > listing.price) {
            payable(msg.sender).transfer(msg.value - listing.price);
        }

        // Update trading volume and rewards
        tradingVolume[msg.sender] += listing.price;
        uint256 reward = (listing.price * volumeRewardRate) / 10000;
        tradingRewards[msg.sender] += reward;

        emit ItemSold(listingId, msg.sender, listing.price);
        emit TradingRewardPaid(msg.sender, reward);
    }

    /**
     * @dev Create an auction
     */
    function createAuction(
        address nftContract,
        uint256 tokenId,
        uint256 startingBid,
        uint256 duration
    ) external nonReentrant whenNotPaused {
        require(IERC721(nftContract).ownerOf(tokenId) == msg.sender, "Not token owner");
        require(IERC721(nftContract).isApprovedForAll(msg.sender, address(this)), "Contract not approved");
        require(startingBid > 0, "Invalid starting bid");
        require(duration >= 3600 && duration <= 7 days, "Invalid duration");

        _auctionIdCounter++;
        uint256 auctionId = _auctionIdCounter;

        auctions[auctionId] = Auction({
            auctionId: auctionId,
            nftContract: nftContract,
            tokenId: tokenId,
            seller: msg.sender,
            startingBid: startingBid,
            currentBid: 0,
            highestBidder: address(0),
            endTime: block.timestamp + duration,
            active: true,
            isCollection: false,
            tokenIds: new uint256[](0)
        });

        userAuctions[msg.sender].push(auctionId);

        emit AuctionCreated(auctionId, nftContract, tokenId, msg.sender, startingBid, block.timestamp + duration);
    }

    /**
     * @dev Create collection-wide auction
     */
    function createCollectionAuction(
        address nftContract,
        uint256[] calldata tokenIds,
        uint256 startingBid,
        uint256 duration
    ) external nonReentrant whenNotPaused {
        require(tokenIds.length > 1 && tokenIds.length <= 20, "Invalid collection size");
        require(startingBid > 0, "Invalid starting bid");
        require(duration >= 3600 && duration <= 7 days, "Invalid duration");

        for (uint256 i = 0; i < tokenIds.length; i++) {
            require(IERC721(nftContract).ownerOf(tokenIds[i]) == msg.sender, "Not owner of all tokens");
        }
        require(IERC721(nftContract).isApprovedForAll(msg.sender, address(this)), "Contract not approved");

        _auctionIdCounter++;
        uint256 auctionId = _auctionIdCounter;

        auctions[auctionId] = Auction({
            auctionId: auctionId,
            nftContract: nftContract,
            tokenId: 0, // Not used for collection auctions
            seller: msg.sender,
            startingBid: startingBid,
            currentBid: 0,
            highestBidder: address(0),
            endTime: block.timestamp + duration,
            active: true,
            isCollection: true,
            tokenIds: tokenIds
        });

        userAuctions[msg.sender].push(auctionId);

        emit AuctionCreated(auctionId, nftContract, 0, msg.sender, startingBid, block.timestamp + duration);
    }

    /**
     * @dev Place bid on auction
     */
    function placeBid(uint256 auctionId) external payable nonReentrant whenNotPaused {
        Auction storage auction = auctions[auctionId];
        require(auction.active, "Auction not active");
        require(block.timestamp < auction.endTime, "Auction ended");
        require(msg.sender != auction.seller, "Seller cannot bid");

        uint256 minBid = auction.currentBid == 0 ? auction.startingBid : auction.currentBid + (auction.currentBid * 5) / 100; // 5% increment
        require(msg.value >= minBid, "Bid too low");

        // Refund previous bidder
        if (auction.highestBidder != address(0)) {
            payable(auction.highestBidder).transfer(auction.currentBid);
        }

        auction.currentBid = msg.value;
        auction.highestBidder = msg.sender;
        auctionBids[auctionId][msg.sender] = msg.value;

        // Extend auction if bid placed in last 10 minutes
        if (auction.endTime - block.timestamp < 600) {
            auction.endTime += 600;
        }

        emit BidPlaced(auctionId, msg.sender, msg.value);
    }

    /**
     * @dev End auction and transfer NFT
     */
    function endAuction(uint256 auctionId) external nonReentrant {
        Auction storage auction = auctions[auctionId];
        require(auction.active, "Auction not active");
        require(block.timestamp >= auction.endTime, "Auction still ongoing");

        auction.active = false;

        if (auction.highestBidder != address(0)) {
            // Calculate fees
            uint256 fee = (auction.currentBid * marketplaceFee) / 10000;
            uint256 sellerAmount = auction.currentBid - fee;

            // Transfer NFT(s)
            if (auction.isCollection) {
                for (uint256 i = 0; i < auction.tokenIds.length; i++) {
                    IERC721(auction.nftContract).safeTransferFrom(
                        auction.seller,
                        auction.highestBidder,
                        auction.tokenIds[i]
                    );
                }
            } else {
                IERC721(auction.nftContract).safeTransferFrom(
                    auction.seller,
                    auction.highestBidder,
                    auction.tokenId
                );
            }

            // Transfer payments
            payable(auction.seller).transfer(sellerAmount);
            payable(feeRecipient).transfer(fee);

            // Update trading volume and rewards
            tradingVolume[auction.highestBidder] += auction.currentBid;
            uint256 reward = (auction.currentBid * volumeRewardRate) / 10000;
            tradingRewards[auction.highestBidder] += reward;

            emit TradingRewardPaid(auction.highestBidder, reward);
        }

        emit AuctionEnded(auctionId, auction.highestBidder, auction.currentBid);
    }

    /**
     * @dev Cancel listing (only seller)
     */
    function cancelListing(uint256 listingId) external {
        Listing storage listing = listings[listingId];
        require(listing.seller == msg.sender, "Not seller");
        require(listing.active, "Listing not active");

        listing.active = false;
    }

    /**
     * @dev Update marketplace fee (admin only)
     */
    function updateMarketplaceFee(uint256 newFee) external onlyRole(ADMIN_ROLE) {
        require(newFee <= MAX_FEE, "Fee too high");
        marketplaceFee = newFee;
    }

    /**
     * @dev Update volume reward rate (admin only)
     */
    function updateVolumeRewardRate(uint256 newRate) external onlyRole(ADMIN_ROLE) {
        require(newRate <= 100, "Rate too high"); // Max 1%
        volumeRewardRate = newRate;
    }

    /**
     * @dev Claim trading rewards
     */
    function claimTradingRewards() external nonReentrant {
        uint256 rewards = tradingRewards[msg.sender];
        require(rewards > 0, "No rewards to claim");

        tradingRewards[msg.sender] = 0;
        payable(msg.sender).transfer(rewards);

        emit TradingRewardPaid(msg.sender, rewards);
    }

    /**
     * @dev Get active listings count
     */
    function getActiveListingsCount() external view returns (uint256) {
        return _listingIdCounter;
    }

    /**
     * @dev Get active auctions count
     */
    function getActiveAuctionsCount() external view returns (uint256) {
        return _auctionIdCounter;
    }

    /**
     * @dev Get user's total trading volume
     */
    function getUserTradingStats(address user) external view returns (uint256 volume, uint256 rewards) {
        return (tradingVolume[user], tradingRewards[user]);
    }

    /**
     * @dev Emergency functions
     */
    function pause() external onlyRole(ADMIN_ROLE) {
        _pause();
    }

    function unpause() external onlyRole(ADMIN_ROLE) {
        _unpause();
    }

    /**
     * @dev Withdraw accumulated fees (admin only)
     */
    function withdrawFees() external onlyRole(ADMIN_ROLE) {
        uint256 balance = address(this).balance;
        payable(feeRecipient).transfer(balance);
    }

    receive() external payable {}
}

