// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title ISovranWealthFund
 * @dev Interface for SovranWealthFund contract to avoid import conflicts
 * Includes both ERC20 and custom SWF functionality
 */
interface ISovranWealthFund is IERC20 {
    // ERC20 functions are inherited from IERC20

    // SWF-specific functions
    function mint(address to, uint256 amount) external;
    function burn(uint256 amount) external;
    function paused() external view returns (bool);
    function pause() external;
    function unpause() external;
    function hasRole(bytes32 role, address account) external view returns (bool);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;

    // Role constants
    function DEFAULT_ADMIN_ROLE() external view returns (bytes32);
    function MINTER_ROLE() external view returns (bytes32);
    function PAUSER_ROLE() external view returns (bytes32);
}

/**
 * @title SovranWealthFund
 * @dev Type casting for using SovranWealthFund as ISovranWealthFund
 */
abstract contract SovranWealthFund is ISovranWealthFund {
}

contracts/LiquidityRewardsVault.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title LiquidityRewardsVault
 * @dev Full-featured LP token staking vault with time-weighted rewards, APY, and lock periods
 * @notice Stake LP tokens to earn rewards over time with flexible APY and optional lock periods
 */
contract LiquidityRewardsVault is Ownable, ReentrancyGuard, Pausable {

    // ========== STATE VARIABLES ==========

    IERC20 public lpToken;
    IERC20 public rewardToken;

    // Staking parameters
    uint256 public rewardRate; // Rewards per second per token staked (scaled by 1e18)
    uint256 public lockPeriod; // Lock period in seconds (default: 7 days)
    uint256 public minimumStake; // Minimum amount to stake (in wei)

    // Global stats
    uint256 public totalStaked;
    uint256 public lastUpdateTime;
    uint256 public rewardPerTokenStored;

    // User data
    struct StakeInfo {
        uint256 amount;           // Amount of LP tokens staked
        uint256 startTime;        // When user first staked
        uint256 lastClaimTime;    // Last time rewards were claimed
        uint256 rewardPerTokenPaid; // Reward per token already paid
        uint256 rewards;          // Pending rewards
    }

    mapping(address => StakeInfo) public stakes;

    // ========== EVENTS ==========

    event Staked(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardsClaimed(address indexed user, uint256 amount);
    event RewardRateUpdated(uint256 oldRate, uint256 newRate);
    event LockPeriodUpdated(uint256 oldPeriod, uint256 newPeriod);
    event MinimumStakeUpdated(uint256 oldMinimum, uint256 newMinimum);
    event EmergencyWithdraw(address indexed user, uint256 amount);
    event RewardsFunded(uint256 amount);

    // ========== CONSTRUCTOR ==========

    /**
     * @param _lpToken Address of the LP token to stake
     * @param _rewardToken Address of the reward token (can be same as LP token)
     * @param _rewardRate Initial reward rate (rewards per second per token, scaled by 1e18)
     * @param _lockPeriod Lock period in seconds (0 for no lock)
     * @param _minimumStake Minimum stake amount in wei (0 for no minimum)
     */
    constructor(
        address _lpToken,
        address _rewardToken,
        uint256 _rewardRate,
        uint256 _lockPeriod,
        uint256 _minimumStake
    ) Ownable(msg.sender) {
        require(_lpToken != address(0), "Invalid LP token");
        require(_rewardToken != address(0), "Invalid reward token");

        lpToken = IERC20(_lpToken);
        rewardToken = IERC20(_rewardToken);
        rewardRate = _rewardRate;
        lockPeriod = _lockPeriod;
        minimumStake = _minimumStake;
        lastUpdateTime = block.timestamp;
    }

    // ========== MODIFIERS ==========

    modifier updateReward(address account) {
        rewardPerTokenStored = rewardPerToken();
        lastUpdateTime = block.timestamp;

        if (account != address(0)) {
            stakes[account].rewards = earned(account);
            stakes[account].rewardPerTokenPaid = rewardPerTokenStored;
        }
        _;
    }

    // ========== VIEW FUNCTIONS ==========

    /**
     * @notice Calculate reward per token
     * @return Reward per token value
     */
    function rewardPerToken() public view returns (uint256) {
        if (totalStaked == 0) {
            return rewardPerTokenStored;
        }

        return rewardPerTokenStored + (
            ((block.timestamp - lastUpdateTime) * rewardRate * 1e18) / totalStaked
        );
    }

    /**
     * @notice Calculate earned rewards for an account
     * @param account User address
     * @return Amount of rewards earned
     */
    function earned(address account) public view returns (uint256) {
        StakeInfo memory stake = stakes[account];
        return (
            (stake.amount * (rewardPerToken() - stake.rewardPerTokenPaid)) / 1e18
        ) + stake.rewards;
    }

    /**
     * @notice Get pending rewards for an account
     * @param account User address
     * @return Pending reward amount
     */
    function pendingRewards(address account) external view returns (uint256) {
        return earned(account);
    }

    /**
     * @notice Calculate current APY based on reward rate
     * @return APY percentage (scaled by 100, e.g., 1500 = 15%)
     */
    function calculateAPY() external view returns (uint256) {
        if (totalStaked == 0) return 0;

        // Annual rewards = rewardRate * seconds per year
        uint256 annualRewards = rewardRate * 365 days;
        // APY = (annualRewards / totalStaked) * 100
        return (annualRewards * 10000) / totalStaked;
    }

    /**
     * @notice Get user stake information
     * @param account User address
     * @return amount Staked amount
     * @return startTime Stake start time
     * @return lastClaimTime Last claim time
     * @return pendingReward Pending rewards
     * @return canWithdraw Whether lock period has passed
     */
    function getUserStake(address account) external view returns (
        uint256 amount,
        uint256 startTime,
        uint256 lastClaimTime,
        uint256 pendingReward,
        bool canWithdraw
    ) {
        StakeInfo memory stake = stakes[account];
        amount = stake.amount;
        startTime = stake.startTime;
        lastClaimTime = stake.lastClaimTime;
        pendingReward = earned(account);
        canWithdraw = block.timestamp >= stake.startTime + lockPeriod;
    }

    // ========== STAKING FUNCTIONS ==========

    /**
     * @notice Stake LP tokens
     * @param amount Amount of LP tokens to stake
     */
    function stake(uint256 amount) external nonReentrant whenNotPaused updateReward(msg.sender) {
        require(amount > 0, "Cannot stake 0");
        require(amount >= minimumStake, "Below minimum stake");

        StakeInfo storage userStake = stakes[msg.sender];

        // SECURITY FIX: Always refresh lock period on new stakes if lock is enabled
        // This prevents users from staking dust, waiting, then adding large amounts to bypass lock
        if (lockPeriod > 0) {
            userStake.startTime = block.timestamp;
        } else if (userStake.amount == 0) {
            // Only set on first stake if no lock period
            userStake.startTime = block.timestamp;
        }

        // Set last claim time on first stake
        if (userStake.amount == 0) {
            userStake.lastClaimTime = block.timestamp;
        }

        // Transfer LP tokens from user
        lpToken.transferFrom(msg.sender, address(this), amount);

        // Update stake info
        userStake.amount += amount;
        totalStaked += amount;

        emit Staked(msg.sender, amount);
    }

    /**
     * @notice Alias for stake() to maintain compatibility
     */
    function deposit(uint256 amount) external nonReentrant whenNotPaused updateReward(msg.sender) {
        require(amount > 0, "Cannot stake 0");
        require(amount >= minimumStake, "Below minimum stake");

        StakeInfo storage userStake = stakes[msg.sender];

        // SECURITY FIX: Always refresh lock period on new stakes if lock is enabled
        if (lockPeriod > 0) {
            userStake.startTime = block.timestamp;
        } else if (userStake.amount == 0) {
            userStake.startTime = block.timestamp;
        }

        if (userStake.amount == 0) {
            userStake.lastClaimTime = block.timestamp;
        }

        lpToken.transferFrom(msg.sender, address(this), amount);
        userStake.amount += amount;
        totalStaked += amount;

        emit Staked(msg.sender, amount);
    }

    /**
     * @notice Withdraw staked LP tokens
     * @param amount Amount to withdraw
     */
    function withdraw(uint256 amount) external nonReentrant updateReward(msg.sender) {
        require(amount > 0, "Cannot withdraw 0");

        StakeInfo storage userStake = stakes[msg.sender];
        require(userStake.amount >= amount, "Insufficient stake");

        // Check lock period
        require(
            block.timestamp >= userStake.startTime + lockPeriod,
            "Lock period not ended"
        );

        // Update stake info
        userStake.amount -= amount;
        totalStaked -= amount;

        // If fully withdrawn, reset start time
        if (userStake.amount == 0) {
            userStake.startTime = 0;
        }

        // Transfer LP tokens back to user
        lpToken.transfer(msg.sender, amount);

        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @notice Claim accumulated rewards
     */
    function claimRewards() external nonReentrant updateReward(msg.sender) {
        uint256 reward = stakes[msg.sender].rewards;
        require(reward > 0, "No rewards to claim");

        stakes[msg.sender].rewards = 0;
        stakes[msg.sender].lastClaimTime = block.timestamp;

        // Transfer reward tokens
        rewardToken.transfer(msg.sender, reward);

        emit RewardsClaimed(msg.sender, reward);
    }

    /**
     * @notice Withdraw stake and claim rewards in one transaction
     * @param amount Amount to withdraw (0 to just claim rewards)
     */
    function exit(uint256 amount) external nonReentrant updateReward(msg.sender) {
        StakeInfo storage userStake = stakes[msg.sender];

        // Withdraw if amount specified
        if (amount > 0) {
            require(userStake.amount >= amount, "Insufficient stake");
            require(
                block.timestamp >= userStake.startTime + lockPeriod,
                "Lock period not ended"
            );

            userStake.amount -= amount;
            totalStaked -= amount;

            if (userStake.amount == 0) {
                userStake.startTime = 0;
            }

            lpToken.transfer(msg.sender, amount);
            emit Withdrawn(msg.sender, amount);
        }

        // Claim rewards if any
        uint256 reward = userStake.rewards;
        if (reward > 0) {
            userStake.rewards = 0;
            userStake.lastClaimTime = block.timestamp;
            rewardToken.transfer(msg.sender, reward);
            emit RewardsClaimed(msg.sender, reward);
        }
    }

    // ========== OWNER FUNCTIONS ==========

    /**
     * @notice Update reward rate
     * @param _rewardRate New reward rate (per second per token, scaled by 1e18)
     */
    function setRewardRate(uint256 _rewardRate) external onlyOwner updateReward(address(0)) {
        uint256 oldRate = rewardRate;
        rewardRate = _rewardRate;
        emit RewardRateUpdated(oldRate, _rewardRate);
    }

    /**
     * @notice Update lock period
     * @param _lockPeriod New lock period in seconds
     */
    function setLockPeriod(uint256 _lockPeriod) external onlyOwner {
        uint256 oldPeriod = lockPeriod;
        lockPeriod = _lockPeriod;
        emit LockPeriodUpdated(oldPeriod, _lockPeriod);
    }

    /**
     * @notice Update minimum stake requirement
     * @param _minimumStake New minimum stake amount
     */
    function setMinimumStake(uint256 _minimumStake) external onlyOwner {
        uint256 oldMinimum = minimumStake;
        minimumStake = _minimumStake;
        emit MinimumStakeUpdated(oldMinimum, _minimumStake);
    }

    /**
     * @notice Fund the contract with reward tokens
     * @param amount Amount of reward tokens to add
     */
    function fundRewards(uint256 amount) external onlyOwner {
        require(amount > 0, "Cannot fund 0");
        rewardToken.transferFrom(msg.sender, address(this), amount);
        emit RewardsFunded(amount);
    }

    /**
     * @notice Pause staking (emergency only)
     */
    function pause() external onlyOwner {
        _pause();
    }

    /**
     * @notice Unpause staking
     */
    function unpause() external onlyOwner {
        _unpause();
    }

    /**
     * @notice Emergency withdraw - allows users to withdraw without lock period check
     * @dev Only callable when paused, for emergency situations
     */
    function emergencyWithdraw() external nonReentrant {
        require(paused(), "Not in emergency mode");

        StakeInfo storage userStake = stakes[msg.sender];
        uint256 amount = userStake.amount;
        require(amount > 0, "No stake to withdraw");

        // Reset stake
        userStake.amount = 0;
        userStake.startTime = 0;
        totalStaked -= amount;

        // Transfer LP tokens back (forfeit rewards in emergency)
        lpToken.transfer(msg.sender, amount);

        emit EmergencyWithdraw(msg.sender, amount);
    }

    /**
     * @notice Recover accidentally sent tokens (not LP or reward tokens)
     * @param token Token address to recover
     * @param amount Amount to recover
     */
    function recoverERC20(address token, uint256 amount) external onlyOwner {
        require(token != address(lpToken), "Cannot recover LP token");
        require(token != address(rewardToken), "Cannot recover reward token");
        IERC20(token).transfer(owner(), amount);
    }

    /**
     * @notice Get balance of user (alias for compatibility)
     * @param user User address
     * @return Staked amount
     */
    function balanceOf(address user) external view returns (uint256) {
        return stakes[user].amount;
    }

    /**
     * @notice Get user staked amount (alias for compatibility)
     * @param user User address
     * @return Staked amount
     */
    function staked(address user) external view returns (uint256) {
        return stakes[user].amount;
    }
}

contracts/MoabiteConstitution.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/extensions/AccessControlEnumerable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";

/**
 * @title MoabiteConstitution
 * @dev Constitutional foundation contract for The Moabite Federation digital nation-state
 * Stores constitutional documents on IPFS and enforces governance rules across all sub-DAOs
 */
contract MoabiteConstitution is AccessControlEnumerable, ReentrancyGuard, Pausable {

    // Role definitions for The Moabite Federation
    bytes32 public constant GRAND_VIZIER_ROLE = keccak256("GRAND_VIZIER_ROLE");
    bytes32 public constant TRIBAL_LEADER_ROLE = keccak256("TRIBAL_LEADER_ROLE");
    bytes32 public constant IMAM_ROLE = keccak256("IMAM_ROLE");
    bytes32 public constant CITIZEN_ROLE = keccak256("CITIZEN_ROLE");

    // Constitutional document structure
    struct ConstitutionalDocument {
        string ipfsCID;           // IPFS hash of the document
        string title;             // Document title
        string documentType;      // "constitution", "amendment", "law", "treaty"
        uint256 ratificationDate; // Timestamp of ratification
        address proposedBy;       // Address that proposed the document
        uint256 votesFor;         // Votes in favor
        uint256 votesAgainst;     // Votes against
        bool isRatified;          // Whether the document is active
        bool isActive;            // Current status
    }

    // Governance proposal structure
    struct GovernanceProposal {
        uint256 id;
        string title;
        string description;
        string ipfsCID;           // IPFS hash of detailed proposal
        address proposer;
        uint256 createdAt;
        uint256 votingEndsAt;
        uint256 votesFor;
        uint256 votesAgainst;
        bool executed;
        bool passed;
        mapping(address => bool) hasVoted;
    }

    // State variables
    mapping(uint256 => ConstitutionalDocument) public constitutionalDocuments;
    mapping(uint256 => GovernanceProposal) public proposals;
    mapping(address => bool) public authorizedContracts; // Contracts that can enforce constitutional rules

    uint256 public nextDocumentId = 1;
    uint256 public nextProposalId = 1;
    uint256 public constant VOTING_PERIOD = 7 days;
    uint256 public constant QUORUM_PERCENTAGE = 30; // 30% of total voters needed

    string public mainConstitutionCID; // Primary constitution IPFS hash
    uint256 public foundingDate;

    // Events
    event ConstitutionalDocumentAdded(uint256 indexed documentId, string ipfsCID, string title, string documentType);
    event DocumentRatified(uint256 indexed documentId, uint256 votesFor, uint256 votesAgainst);
    event ProposalCreated(uint256 indexed proposalId, address proposer, string title);
    event ProposalVoted(uint256 indexed proposalId, address voter, bool support);
    event ProposalExecuted(uint256 indexed proposalId, bool passed);
    event ContractAuthorized(address indexed contractAddress, bool authorized);

    modifier onlyGrandVizier() {
        require(hasRole(GRAND_VIZIER_ROLE, msg.sender), "MoabiteConstitution: Caller is not Grand Vizier");
        _;
    }

    modifier onlyTribalLeaderOrAbove() {
        require(
            hasRole(GRAND_VIZIER_ROLE, msg.sender) || 
            hasRole(TRIBAL_LEADER_ROLE, msg.sender),
            "MoabiteConstitution: Insufficient authority"
        );
        _;
    }

    modifier onlyCitizen() {
        require(hasRole(CITIZEN_ROLE, msg.sender), "MoabiteConstitution: Must be citizen");
        _;
    }

    constructor(string memory _mainConstitutionCID, address _grandVizier) {
        require(bytes(_mainConstitutionCID).length > 0, "Constitution CID required");
        require(_grandVizier != address(0), "Invalid Grand Vizier address");

        mainConstitutionCID = _mainConstitutionCID;
        foundingDate = block.timestamp;

        // Setup roles
        _grantRole(DEFAULT_ADMIN_ROLE, _grandVizier);
        _grantRole(GRAND_VIZIER_ROLE, _grandVizier);

        // Add founding constitutional document
        constitutionalDocuments[1] = ConstitutionalDocument({
            ipfsCID: _mainConstitutionCID,
            title: "The Moabite Federation Constitution",
            documentType: "constitution",
            ratificationDate: block.timestamp,
            proposedBy: _grandVizier,
            votesFor: 1,
            votesAgainst: 0,
            isRatified: true,
            isActive: true
        });

        emit ConstitutionalDocumentAdded(1, _mainConstitutionCID, "The Moabite Federation Constitution", "constitution");
        emit DocumentRatified(1, 1, 0);
    }

    /**
     * @dev Add a new constitutional document (amendment, law, treaty)
     */
    function addConstitutionalDocument(
        string memory _ipfsCID,
        string memory _title,
        string memory _documentType
    ) external onlyTribalLeaderOrAbove returns (uint256) {
        require(bytes(_ipfsCID).length > 0, "IPFS CID required");
        require(bytes(_title).length > 0, "Title required");

        uint256 documentId = nextDocumentId++;

        constitutionalDocuments[documentId] = ConstitutionalDocument({
            ipfsCID: _ipfsCID,
            title: _title,
            documentType: _documentType,
            ratificationDate: 0,
            proposedBy: msg.sender,
            votesFor: 0,
            votesAgainst: 0,
            isRatified: false,
            isActive: false
        });

        emit ConstitutionalDocumentAdded(documentId, _ipfsCID, _title, _documentType);
        return documentId;
    }

    /**
     * @dev Create a governance proposal
     */
    function createProposal(
        string memory _title,
        string memory _description,
        string memory _ipfsCID
    ) external onlyCitizen returns (uint256) {
        require(bytes(_title).length > 0, "Title required");
        require(bytes(_description).length > 0, "Description required");

        uint256 proposalId = nextProposalId++;
        GovernanceProposal storage proposal = proposals[proposalId];

        proposal.id = proposalId;
        proposal.title = _title;
        proposal.description = _description;
        proposal.ipfsCID = _ipfsCID;
        proposal.proposer = msg.sender;
        proposal.createdAt = block.timestamp;
        proposal.votingEndsAt = block.timestamp + VOTING_PERIOD;
        proposal.executed = false;
        proposal.passed = false;

        emit ProposalCreated(proposalId, msg.sender, _title);
        return proposalId;
    }

    /**
     * @dev Vote on a governance proposal
     */
    function voteOnProposal(uint256 _proposalId, bool _support) external onlyCitizen {
        GovernanceProposal storage proposal = proposals[_proposalId];
        require(proposal.id != 0, "Proposal does not exist");
        require(block.timestamp <= proposal.votingEndsAt, "Voting period ended");
        require(!proposal.hasVoted[msg.sender], "Already voted");

        proposal.hasVoted[msg.sender] = true;

        if (_support) {
            proposal.votesFor++;
        } else {
            proposal.votesAgainst++;
        }

        emit ProposalVoted(_proposalId, msg.sender, _support);
    }

    /**
     * @dev Execute a proposal after voting period
     */
    function executeProposal(uint256 _proposalId) external {
        GovernanceProposal storage proposal = proposals[_proposalId];
        require(proposal.id != 0, "Proposal does not exist");
        require(block.timestamp > proposal.votingEndsAt, "Voting still active");
        require(!proposal.executed, "Proposal already executed");

        uint256 totalVotes = proposal.votesFor + proposal.votesAgainst;
        uint256 citizenCount = getRoleMemberCount(CITIZEN_ROLE);

        // Check quorum (30% of citizens must vote)
        require(totalVotes >= (citizenCount * QUORUM_PERCENTAGE) / 100, "Quorum not met");

        proposal.executed = true;
        proposal.passed = proposal.votesFor > proposal.votesAgainst;

        emit ProposalExecuted(_proposalId, proposal.passed);
    }

    /**
     * @dev Grant citizenship (SovranID NFT integration)
     */
    function grantCitizenship(address _citizen) external onlyTribalLeaderOrAbove {
        require(_citizen != address(0), "Invalid citizen address");
        _grantRole(CITIZEN_ROLE, _citizen);
    }

    /**
     * @dev Revoke citizenship
     */
    function revokeCitizenship(address _citizen) external onlyGrandVizier {
        _revokeRole(CITIZEN_ROLE, _citizen);
    }

    /**
     * @dev Authorize a contract to enforce constitutional rules
     */
    function authorizeContract(address _contract, bool _authorized) external onlyGrandVizier {
        require(_contract != address(0), "Invalid contract address");
        authorizedContracts[_contract] = _authorized;
        emit ContractAuthorized(_contract, _authorized);
    }

    /**
     * @dev Check if an action complies with constitutional rules
     */
    function isActionConstitutional(
        address _actor,
        string memory _actionType,
        bytes memory _actionData
    ) external view returns (bool) {
        require(authorizedContracts[msg.sender], "Unauthorized contract");

        // Basic constitutional checks
        if (!hasRole(CITIZEN_ROLE, _actor)) {
            return false; // Non-citizens cannot perform constitutional actions
        }

        // Additional rule checks can be added here based on action type
        return true;
    }

    /**
     * @dev Get constitutional document details
     */
    function getConstitutionalDocument(uint256 _documentId) external view returns (
        string memory ipfsCID,
        string memory title,
        string memory documentType,
        uint256 ratificationDate,
        address proposedBy,
        bool isRatified,
        bool isActive
    ) {
        ConstitutionalDocument storage doc = constitutionalDocuments[_documentId];
        return (
            doc.ipfsCID,
            doc.title,
            doc.documentType,
            doc.ratificationDate,
            doc.proposedBy,
            doc.isRatified,
            doc.isActive
        );
    }

    /**
     * @dev Get proposal details
     */
    function getProposal(uint256 _proposalId) external view returns (
        string memory title,
        string memory description,
        string memory ipfsCID,
        address proposer,
        uint256 createdAt,
        uint256 votingEndsAt,
        uint256 votesFor,
        uint256 votesAgainst,
        bool executed,
        bool passed
    ) {
        GovernanceProposal storage proposal = proposals[_proposalId];
        return (
            proposal.title,
            proposal.description,
            proposal.ipfsCID,
            proposal.proposer,
            proposal.createdAt,
            proposal.votingEndsAt,
            proposal.votesFor,
            proposal.votesAgainst,
            proposal.executed,
            proposal.passed
        );
    }

    /**
     * @dev Emergency pause (Grand Vizier only)
     */
    function pause() external onlyGrandVizier {
        _pause();
    }

    /**
     * @dev Resume operations
     */
    function unpause() external onlyGrandVizier {
        _unpause();
    }
}

contracts/MultiSigWallet.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title Multi-Signature Wallet for MetalOfTheGods Treasury Operations
 * @dev Secure multi-signature wallet requiring multiple confirmations for critical operations
 * @author SWF Development Team
 */
contract MultiSigWallet is ReentrancyGuard {

    // Events
    event Deposit(address indexed sender, uint256 amount, uint256 balance);
    event SubmitTransaction(
        address indexed owner,
        uint256 indexed txIndex,
        address indexed to,
        uint256 value,
        bytes data
    );
    event ConfirmTransaction(address indexed owner, uint256 indexed txIndex);
    event RevokeConfirmation(address indexed owner, uint256 indexed txIndex);
    event ExecuteTransaction(address indexed owner, uint256 indexed txIndex);
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event RequirementChanged(uint256 required);

    // State variables
    address[] public owners;
    mapping(address => bool) public isOwner;
    uint256 public numConfirmationsRequired;

    struct Transaction {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint256 numConfirmations;
        uint256 deadline;
        string description;
    }

    // mapping from tx index => owner => bool
    mapping(uint256 => mapping(address => bool)) public isConfirmed;
    Transaction[] public transactions;

    // Modifiers
    modifier onlyOwner() {
        require(isOwner[msg.sender], "Not owner");
        _;
    }

    modifier txExists(uint256 _txIndex) {
        require(_txIndex < transactions.length, "Transaction does not exist");
        _;
    }

    modifier notExecuted(uint256 _txIndex) {
        require(!transactions[_txIndex].executed, "Transaction already executed");
        _;
    }

    modifier notConfirmed(uint256 _txIndex) {
        require(!isConfirmed[_txIndex][msg.sender], "Transaction already confirmed");
        _;
    }

    modifier validRequirement(uint256 _ownerCount, uint256 _required) {
        require(
            _required > 0 && 
            _required <= _ownerCount && 
            _ownerCount > 0,
            "Invalid requirement"
        );
        _;
    }

    /**
     * @dev Contract constructor sets initial owners and required number of confirmations
     * @param _owners List of initial owners
     * @param _numConfirmationsRequired Number of required confirmations
     */
    constructor(address[] memory _owners, uint256 _numConfirmationsRequired)
        validRequirement(_owners.length, _numConfirmationsRequired)
    {
        require(_owners.length > 0, "Owners required");

        for (uint256 i = 0; i < _owners.length; i++) {
            address owner = _owners[i];

            require(owner != address(0), "Invalid owner");
            require(!isOwner[owner], "Owner not unique");

            isOwner[owner] = true;
            owners.push(owner);
        }

        numConfirmationsRequired = _numConfirmationsRequired;
    }

    /**
     * @dev Allows an owner to submit and confirm a transaction
     * @param _to Destination address
     * @param _value Ether value
     * @param _data Transaction data payload
     * @param _description Human readable description
     * @param _deadline Execution deadline timestamp
     */
    function submitTransaction(
        address _to,
        uint256 _value,
        bytes memory _data,
        string memory _description,
        uint256 _deadline
    ) public onlyOwner {
        require(_deadline > block.timestamp, "Deadline must be in future");

        uint256 txIndex = transactions.length;

        transactions.push(
            Transaction({
                to: _to,
                value: _value,
                data: _data,
                executed: false,
                numConfirmations: 0,
                deadline: _deadline,
                description: _description
            })
        );

        emit SubmitTransaction(msg.sender, txIndex, _to, _value, _data);
    }

    /**
     * @dev Allows an owner to confirm a transaction
     * @param _txIndex Transaction index
     */
    function confirmTransaction(uint256 _txIndex)
        public
        onlyOwner
        txExists(_txIndex)
        notExecuted(_txIndex)
        notConfirmed(_txIndex)
    {
        require(
            block.timestamp <= transactions[_txIndex].deadline,
            "Transaction deadline expired"
        );

        Transaction storage transaction = transactions[_txIndex];
        transaction.numConfirmations += 1;
        isConfirmed[_txIndex][msg.sender] = true;

        emit ConfirmTransaction(msg.sender, _txIndex);
    }

    /**
     * @dev Allows an owner to execute a confirmed transaction
     * @param _txIndex Transaction index
     */
    function executeTransaction(uint256 _txIndex)
        public
        onlyOwner
        txExists(_txIndex)
        notExecuted(_txIndex)
        nonReentrant
    {
        Transaction storage transaction = transactions[_txIndex];

        require(
            transaction.numConfirmations >= numConfirmationsRequired,
            "Cannot execute transaction"
        );

        require(
            block.timestamp <= transaction.deadline,
            "Transaction deadline expired"
        );

        transaction.executed = true;

        (bool success, ) = transaction.to.call{value: transaction.value}(
            transaction.data
        );
        require(success, "Transaction failed");

        emit ExecuteTransaction(msg.sender, _txIndex);
    }

    /**
     * @dev Allows an owner to revoke a confirmation for a transaction
     * @param _txIndex Transaction index
     */
    function revokeConfirmation(uint256 _txIndex)
        public
        onlyOwner
        txExists(_txIndex)
        notExecuted(_txIndex)
    {
        require(isConfirmed[_txIndex][msg.sender], "Transaction not confirmed");

        Transaction storage transaction = transactions[_txIndex];
        transaction.numConfirmations -= 1;
        isConfirmed[_txIndex][msg.sender] = false;

        emit RevokeConfirmation(msg.sender, _txIndex);
    }

    /**
     * @dev Add a new owner (requires multi-sig approval)
     * @param _owner Address of new owner
     */
    function addOwner(address _owner) public onlyOwner {
        require(_owner != address(0), "Invalid owner address");
        require(!isOwner[_owner], "Owner already exists");
        require(owners.length < 10, "Maximum owners reached");

        // This function should be called through submitTransaction for multi-sig approval
        isOwner[_owner] = true;
        owners.push(_owner);

        emit OwnerAdded(_owner);
    }

    /**
     * @dev Remove an owner (requires multi-sig approval)
     * @param _owner Address of owner to remove
     */
    function removeOwner(address _owner) public onlyOwner {
        require(isOwner[_owner], "Not an owner");
        require(owners.length > numConfirmationsRequired, "Cannot remove owner");

        isOwner[_owner] = false;

        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == _owner) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                break;
            }
        }

        emit OwnerRemoved(_owner);
    }

    /**
     * @dev Change the number of required confirmations (requires multi-sig approval)
     * @param _numConfirmationsRequired New requirement
     */
    function changeRequirement(uint256 _numConfirmationsRequired)
        public
        onlyOwner
        validRequirement(owners.length, _numConfirmationsRequired)
    {
        numConfirmationsRequired = _numConfirmationsRequired;
        emit RequirementChanged(_numConfirmationsRequired);
    }

    /**
     * @dev Emergency function to pause all operations for security incidents
     */
    function emergencyPause() public onlyOwner {
        // This would integrate with the main contract's pause functionality
        // Implementation depends on how the pause mechanism is structured
    }

    // View functions
    function getOwners() public view returns (address[] memory) {
        return owners;
    }

    function getTransactionCount() public view returns (uint256) {
        return transactions.length;
    }

    function getTransaction(uint256 _txIndex)
        public
        view
        returns (
            address to,
            uint256 value,
            bytes memory data,
            bool executed,
            uint256 numConfirmations,
            uint256 deadline,
            string memory description
        )
    {
        Transaction storage transaction = transactions[_txIndex];

        return (
            transaction.to,
            transaction.value,
            transaction.data,
            transaction.executed,
            transaction.numConfirmations,
            transaction.deadline,
            transaction.description
        );
    }

    /**
     * @dev Get pending transactions that need confirmation
     * @return Array of pending transaction indices
     */
    function getPendingTransactions() public view returns (uint256[] memory) {
        uint256[] memory tempPending = new uint256[](transactions.length);
        uint256 pendingCount = 0;

        for (uint256 i = 0; i < transactions.length; i++) {
            if (!transactions[i].executed && 
                transactions[i].numConfirmations < numConfirmationsRequired &&
                block.timestamp <= transactions[i].deadline) {
                tempPending[pendingCount] = i;
                pendingCount++;
            }
        }

        uint256[] memory pending = new uint256[](pendingCount);
        for (uint256 i = 0; i < pendingCount; i++) {
            pending[i] = tempPending[i];
        }

        return pending;
    }

    /**
     * @dev Check if transaction is confirmed by specific owner
     * @param _txIndex Transaction index
     * @param _owner Owner address
     * @return Whether the transaction is confirmed by the owner
     */
    function isConfirmedBy(uint256 _txIndex, address _owner) 
        public 
        view 
        returns (bool) 
    {
        return isConfirmed[_txIndex][_owner];
    }

    // Fallback function to receive Ether
    receive() external payable {
        emit Deposit(msg.sender, msg.value, address(this).balance);
    }

    fallback() external payable {
        emit Deposit(msg.sender, msg.value, address(this).balance);
    }
}

contracts/NFTMarketplace.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import "@openzeppelin/contracts-upgradeable/utils/ReentrancyGuardUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/utils/PausableUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title MetalOfTheGods NFT Marketplace
 * @dev Secure marketplace with escrow, auctions, and royalty distribution
 * @author SWF Development Team
 */
contract NFTMarketplace is 
    Initializable,
    ReentrancyGuardUpgradeable,
    PausableUpgradeable,
    AccessControlUpgradeable,
    UUPSUpgradeable
{
    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant UPGRADER_ROLE = keccak256("UPGRADER_ROLE");

    struct Listing {
        uint256 tokenId;
        address seller;
        uint256 price;
        bool active;
        uint256 createdAt;
        uint256 expiresAt;
        address paymentToken; // address(0) for BNB, otherwise ERC20
    }

    struct Auction {
        uint256 tokenId;
        address seller;
        uint256 startingPrice;
        uint256 currentBid;
        address currentBidder;
        uint256 startTime;
        uint256 endTime;
        bool active;
        bool isReserveAuction;
        uint256 reservePrice;
        address paymentToken;
    }

    struct Offer {
        uint256 tokenId;
        address buyer;
        uint256 price;
        uint256 expiresAt;
        bool active;
        address paymentToken;
    }

    // Contract state
    IERC721 public nftContract;
    IERC20 public swfToken;

    uint256 public marketplaceFee; // Basis points (e.g., 250 = 2.5%)
    uint256 public royaltyFee; // Basis points for original creators
    address public feeRecipient;
    address public royaltyRecipient;

    uint256 private _listingIdCounter;
    uint256 private _auctionIdCounter;
    uint256 private _offerIdCounter;

    mapping(uint256 => Listing) public listings; // listingId => Listing
    mapping(uint256 => Auction) public auctions; // auctionId => Auction
    mapping(uint256 => Offer) public offers; // offerId => Offer
    mapping(uint256 => uint256[]) public tokenOffers; // tokenId => offerIds
    mapping(address => uint256) public pendingReturns; // For failed auction bids

    // Events
    event ListingCreated(uint256 indexed listingId, uint256 indexed tokenId, address indexed seller, uint256 price);
    event ListingCanceled(uint256 indexed listingId, uint256 indexed tokenId);
    event ItemSold(uint256 indexed listingId, uint256 indexed tokenId, address indexed buyer, uint256 price);

    event AuctionCreated(uint256 indexed auctionId, uint256 indexed tokenId, address indexed seller, uint256 startingPrice, uint256 endTime);
    event BidPlaced(uint256 indexed auctionId, address indexed bidder, uint256 amount);
    event AuctionEnded(uint256 indexed auctionId, address indexed winner, uint256 amount);
    event AuctionCanceled(uint256 indexed auctionId, uint256 indexed tokenId);

    event OfferMade(uint256 indexed offerId, uint256 indexed tokenId, address indexed buyer, uint256 price);
    event OfferAccepted(uint256 indexed offerId, uint256 indexed tokenId, address indexed seller);
    event OfferCanceled(uint256 indexed offerId, uint256 indexed tokenId);

    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() {
        _disableInitializers();
    }

    function initialize(
        address _nftContract,
        address _swfToken,
        address _feeRecipient,
        address _royaltyRecipient,
        uint256 _marketplaceFee,
        uint256 _royaltyFee
    ) initializer public {
        __ReentrancyGuard_init();
        __Pausable_init();
        __AccessControl_init();
        __UUPSUpgradeable_init();

        require(_nftContract != address(0), "Invalid NFT contract");
        require(_swfToken != address(0), "Invalid SWF token");
        require(_feeRecipient != address(0), "Invalid fee recipient");
        require(_marketplaceFee <= 1000, "Fee too high"); // Max 10%
        require(_royaltyFee <= 1000, "Royalty too high"); // Max 10%

        nftContract = IERC721(_nftContract);
        swfToken = IERC20(_swfToken);
        feeRecipient = _feeRecipient;
        royaltyRecipient = _royaltyRecipient;
        marketplaceFee = _marketplaceFee;
        royaltyFee = _royaltyFee;

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
        _grantRole(UPGRADER_ROLE, msg.sender);
    }

    // Fixed price listings
    function createListing(
        uint256 tokenId,
        uint256 price,
        uint256 duration,
        address paymentToken
    ) external whenNotPaused nonReentrant {
        require(nftContract.ownerOf(tokenId) == msg.sender, "Not token owner");
        require(nftContract.getApproved(tokenId) == address(this) || 
                nftContract.isApprovedForAll(msg.sender, address(this)), "Not approved");
        require(price > 0, "Price must be greater than 0");
        require(duration > 0 && duration <= 365 days, "Invalid duration");

        uint256 listingId = _listingIdCounter++;
        uint256 expiresAt = block.timestamp + duration;

        listings[listingId] = Listing({
            tokenId: tokenId,
            seller: msg.sender,
            price: price,
            active: true,
            createdAt: block.timestamp,
            expiresAt: expiresAt,
            paymentToken: paymentToken
        });

        emit ListingCreated(listingId, tokenId, msg.sender, price);
    }

    function buyItem(uint256 listingId) external payable whenNotPaused nonReentrant {
        Listing storage listing = listings[listingId];
        require(listing.active, "Listing not active");
        require(block.timestamp <= listing.expiresAt, "Listing expired");
        require(msg.sender != listing.seller, "Cannot buy own item");

        uint256 totalPrice = listing.price;
        listing.active = false;

        // Handle payment
        if (listing.paymentToken == address(0)) {
            require(msg.value >= totalPrice, "Insufficient payment");
            _distributeFunds(listing.seller, totalPrice, msg.value);
        } else {
            IERC20 paymentToken = IERC20(listing.paymentToken);
            require(paymentToken.transferFrom(msg.sender, address(this), totalPrice), "Payment failed");
            _distributeFundsERC20(listing.seller, totalPrice, paymentToken);
        }

        // Transfer NFT
        nftContract.safeTransferFrom(listing.seller, msg.sender, listing.tokenId);

        emit ItemSold(listingId, listing.tokenId, msg.sender, totalPrice);
    }

    function cancelListing(uint256 listingId) external {
        Listing storage listing = listings[listingId];
        require(listing.seller == msg.sender || hasRole(ADMIN_ROLE, msg.sender), "Not authorized");
        require(listing.active, "Listing not active");

        listing.active = false;
        emit ListingCanceled(listingId, listing.tokenId);
    }

    // Auction functionality
    function createAuction(
        uint256 tokenId,
        uint256 startingPrice,
        uint256 duration,
        bool isReserveAuction,
        uint256 reservePrice,
        address paymentToken
    ) external whenNotPaused nonReentrant {
        require(nftContract.ownerOf(tokenId) == msg.sender, "Not token owner");
        require(nftContract.getApproved(tokenId) == address(this) || 
                nftContract.isApprovedForAll(msg.sender, address(this)), "Not approved");
        require(startingPrice > 0, "Starting price must be greater than 0");
        require(duration >= 1 hours && duration <= 30 days, "Invalid duration");

        if (isReserveAuction) {
            require(reservePrice >= startingPrice, "Reserve below starting price");
        }

        uint256 auctionId = _auctionIdCounter++;
        uint256 endTime = block.timestamp + duration;

        auctions[auctionId] = Auction({
            tokenId: tokenId,
            seller: msg.sender,
            startingPrice: startingPrice,
            currentBid: 0,
            currentBidder: address(0),
            startTime: block.timestamp,
            endTime: endTime,
            active: true,
            isReserveAuction: isReserveAuction,
            reservePrice: reservePrice,
            paymentToken: paymentToken
        });

        emit AuctionCreated(auctionId, tokenId, msg.sender, startingPrice, endTime);
    }

    function placeBid(uint256 auctionId) external payable whenNotPaused nonReentrant {
        Auction storage auction = auctions[auctionId];
        require(auction.active, "Auction not active");
        require(block.timestamp < auction.endTime, "Auction ended");
        require(msg.sender != auction.seller, "Cannot bid on own auction");

        uint256 bidAmount;
        if (auction.paymentToken == address(0)) {
            bidAmount = msg.value;
        } else {
            revert("ERC20 bidding not implemented in this version");
        }

        require(bidAmount >= auction.startingPrice, "Bid below starting price");
        require(bidAmount > auction.currentBid, "Bid too low");

        // Refund previous bidder
        if (auction.currentBidder != address(0)) {
            pendingReturns[auction.currentBidder] += auction.currentBid;
        }

        auction.currentBid = bidAmount;
        auction.currentBidder = msg.sender;

        // Extend auction if bid placed in last 15 minutes
        if (auction.endTime - block.timestamp < 15 minutes) {
            auction.endTime = block.timestamp + 15 minutes;
        }

        emit BidPlaced(auctionId, msg.sender, bidAmount);
    }

    function endAuction(uint256 auctionId) external nonReentrant {
        Auction storage auction = auctions[auctionId];
        require(auction.active, "Auction not active");
        require(block.timestamp >= auction.endTime, "Auction still active");

        auction.active = false;

        if (auction.currentBidder == address(0) || 
            (auction.isReserveAuction && auction.currentBid < auction.reservePrice)) {
            // No bids or reserve not met
            if (auction.currentBidder != address(0)) {
                pendingReturns[auction.currentBidder] += auction.currentBid;
            }
            emit AuctionCanceled(auctionId, auction.tokenId);
        } else {
            // Successful auction
            _distributeFunds(auction.seller, auction.currentBid, auction.currentBid);
            nftContract.safeTransferFrom(auction.seller, auction.currentBidder, auction.tokenId);
            emit AuctionEnded(auctionId, auction.currentBidder, auction.currentBid);
        }
    }

    function withdraw() external nonReentrant {
        uint256 amount = pendingReturns[msg.sender];
        require(amount > 0, "No funds to withdraw");

        pendingReturns[msg.sender] = 0;
        (bool success, ) = payable(msg.sender).call{value: amount}("");
        require(success, "Withdrawal failed");
    }

    // Offer functionality
    function makeOffer(
        uint256 tokenId,
        uint256 price,
        uint256 duration,
        address paymentToken
    ) external whenNotPaused nonReentrant {
        require(nftContract.ownerOf(tokenId) != msg.sender, "Cannot offer on own token");
        require(price > 0, "Price must be greater than 0");
        require(duration > 0 && duration <= 30 days, "Invalid duration");

        if (paymentToken != address(0)) {
            IERC20 token = IERC20(paymentToken);
            require(token.transferFrom(msg.sender, address(this), price), "Payment transfer failed");
        }

        uint256 offerId = _offerIdCounter++;
        uint256 expiresAt = block.timestamp + duration;

        offers[offerId] = Offer({
            tokenId: tokenId,
            buyer: msg.sender,
            price: price,
            expiresAt: expiresAt,
            active: true,
            paymentToken: paymentToken
        });

        tokenOffers[tokenId].push(offerId);

        emit OfferMade(offerId, tokenId, msg.sender, price);
    }

    function acceptOffer(uint256 offerId) external whenNotPaused nonReentrant {
        Offer storage offer = offers[offerId];
        require(offer.active, "Offer not active");
        require(block.timestamp <= offer.expiresAt, "Offer expired");
        require(nftContract.ownerOf(offer.tokenId) == msg.sender, "Not token owner");
        require(nftContract.getApproved(offer.tokenId) == address(this) || 
                nftContract.isApprovedForAll(msg.sender, address(this)), "Not approved");

        offer.active = false;

        // Handle payment
        if (offer.paymentToken == address(0)) {
            _distributeFunds(msg.sender, offer.price, offer.price);
        } else {
            IERC20 paymentToken = IERC20(offer.paymentToken);
            _distributeFundsERC20(msg.sender, offer.price, paymentToken);
        }

        // Transfer NFT
        nftContract.safeTransferFrom(msg.sender, offer.buyer, offer.tokenId);

        emit OfferAccepted(offerId, offer.tokenId, msg.sender);
    }

    function cancelOffer(uint256 offerId) external {
        Offer storage offer = offers[offerId];
        require(offer.buyer == msg.sender || hasRole(ADMIN_ROLE, msg.sender), "Not authorized");
        require(offer.active, "Offer not active");

        offer.active = false;

        // Refund if ERC20 payment was escrowed
        if (offer.paymentToken != address(0)) {
            IERC20 paymentToken = IERC20(offer.paymentToken);
            require(paymentToken.transfer(offer.buyer, offer.price), "Refund failed");
        }

        emit OfferCanceled(offerId, offer.tokenId);
    }

    // Internal functions
    function _distributeFunds(address seller, uint256 totalAmount, uint256 receivedAmount) internal {
        uint256 marketplaceFeeAmount = (totalAmount * marketplaceFee) / 10000;
        uint256 royaltyAmount = (totalAmount * royaltyFee) / 10000;
        uint256 sellerAmount = totalAmount - marketplaceFeeAmount - royaltyAmount;

        // Transfer fees
        if (marketplaceFeeAmount > 0) {
            (bool success1, ) = payable(feeRecipient).call{value: marketplaceFeeAmount}("");
            require(success1, "Fee transfer failed");
        }

        if (royaltyAmount > 0) {
            (bool success2, ) = payable(royaltyRecipient).call{value: royaltyAmount}("");
            require(success2, "Royalty transfer failed");
        }

        // Transfer to seller
        (bool success3, ) = payable(seller).call{value: sellerAmount}("");
        require(success3, "Seller payment failed");

        // Refund excess
        if (receivedAmount > totalAmount) {
            (bool success4, ) = payable(msg.sender).call{value: receivedAmount - totalAmount}("");
            require(success4, "Refund failed");
        }
    }

    function _distributeFundsERC20(address seller, uint256 totalAmount, IERC20 token) internal {
        uint256 marketplaceFeeAmount = (totalAmount * marketplaceFee) / 10000;
        uint256 royaltyAmount = (totalAmount * royaltyFee) / 10000;
        uint256 sellerAmount = totalAmount - marketplaceFeeAmount - royaltyAmount;

        if (marketplaceFeeAmount > 0) {
            require(token.transfer(feeRecipient, marketplaceFeeAmount), "Fee transfer failed");
        }

        if (royaltyAmount > 0) {
            require(token.transfer(royaltyRecipient, royaltyAmount), "Royalty transfer failed");
        }

        require(token.transfer(seller, sellerAmount), "Seller payment failed");
    }

    // View functions
    function getActiveListing(uint256 tokenId) external view returns (uint256, Listing memory) {
        for (uint256 i = 0; i < _listingIdCounter; i++) {
            if (listings[i].tokenId == tokenId && listings[i].active && 
                block.timestamp <= listings[i].expiresAt) {
                return (i, listings[i]);
            }
        }
        revert("No active listing");
    }

    function getActiveAuction(uint256 tokenId) external view returns (uint256, Auction memory) {
        for (uint256 i = 0; i < _auctionIdCounter; i++) {
            if (auctions[i].tokenId == tokenId && auctions[i].active) {
                return (i, auctions[i]);
            }
        }
        revert("No active auction");
    }

    function getTokenOffers(uint256 tokenId) external view returns (uint256[] memory) {
        return tokenOffers[tokenId];
    }

    // Administrative functions
    function updateFees(uint256 _marketplaceFee, uint256 _royaltyFee) external onlyRole(ADMIN_ROLE) {
        require(_marketplaceFee <= 1000, "Marketplace fee too high");
        require(_royaltyFee <= 1000, "Royalty fee too high");
        marketplaceFee = _marketplaceFee;
        royaltyFee = _royaltyFee;
    }

    function updateRecipients(address _feeRecipient, address _royaltyRecipient) external onlyRole(ADMIN_ROLE) {
        require(_feeRecipient != address(0), "Invalid fee recipient");
        require(_royaltyRecipient != address(0), "Invalid royalty recipient");
        feeRecipient = _feeRecipient;
        royaltyRecipient = _royaltyRecipient;
    }

    function pause() public onlyRole(PAUSER_ROLE) {
        _pause();
    }

    function unpause() public onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    function _authorizeUpgrade(address newImplementation) internal onlyRole(UPGRADER_ROLE) override {}

    // Emergency functions
    function emergencyWithdraw(address token, uint256 amount) external onlyRole(ADMIN_ROLE) {
        if (token == address(0)) {
            (bool success, ) = payable(msg.sender).call{value: amount}("");
            require(success, "Withdrawal failed");
        } else {
            IERC20(token).transfer(msg.sender, amount);
        }
    }
}

