// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title SoloMethodEngine
 * @notice Staking contract for SWF tokens with adjustable APR
 * @dev This contract allows users to stake SWF tokens and earn rewards based on the APR
 */
contract SoloMethodEngine is Ownable {
    // SWF token contract
    IERC20 public stakingToken;

    // Total tokens staked
    uint256 public totalStaked;

    // APR in basis points (25% = 2500 basis points)
    uint256 public aprBasisPoints = 2500;

    // Last update timestamp
    uint256 public lastUpdate;

    // User staking information
    mapping(address => uint256) public staked;
    mapping(address => uint256) public rewardDebt;
    mapping(address => uint256) public lastStaked;

    // Constants for calculations
    uint256 public constant BPS_DIVISOR = 10000;
    uint256 public constant SECONDS_IN_YEAR = 31536000;

    // Events
    event Staked(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event RewardPaid(address indexed user, uint256 reward);
    event APRUpdated(uint256 oldApr, uint256 newApr);

    /**
     * @notice Initializes the SoloMethodEngine contract
     * @param _token Address of the staking token (SWF)
     * @param initialOwner Address of the initial owner
     */
    constructor(address _token, address initialOwner) Ownable(initialOwner) {
        require(_token != address(0), "Invalid token address");
        stakingToken = IERC20(_token);
    }

    /**
     * @notice Sets the APR for staking rewards
     * @param _bps APR in basis points (100 basis points = 1%)
     */
    function setAPR(uint256 _bps) external onlyOwner {
        require(_bps <= 5000, "APR too high"); // Max 50%
        uint256 oldApr = aprBasisPoints;
        aprBasisPoints = _bps;
        emit APRUpdated(oldApr, _bps);
    }

    /**
     * @notice Allows users to stake tokens
     * @param amount Amount of tokens to stake
     */
    function stake(uint256 amount) external {
        require(amount > 0, "Stake more than 0");
        _updateRewards(msg.sender);
        stakingToken.transferFrom(msg.sender, address(this), amount);
        staked[msg.sender] += amount;
        totalStaked += amount;
        lastStaked[msg.sender] = block.timestamp;
        emit Staked(msg.sender, amount);
    }

    /**
     * @notice Allows users to withdraw their staked tokens
     * @param amount Amount of tokens to withdraw
     */
    function withdraw(uint256 amount) external {
        require(amount > 0, "Withdraw more than 0");
        require(staked[msg.sender] >= amount, "Not enough staked");
        _updateRewards(msg.sender);
        staked[msg.sender] -= amount;
        totalStaked -= amount;
        stakingToken.transfer(msg.sender, amount);
        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @notice Allows users to claim their earned rewards
     */
    function claimRewards() external {
        uint256 reward = earned(msg.sender);
        require(reward > 0, "No rewards to claim");
        rewardDebt[msg.sender] = 0;
        lastStaked[msg.sender] = block.timestamp;
        stakingToken.transfer(msg.sender, reward);
        emit RewardPaid(msg.sender, reward);
    }

    /**
     * @notice Updates the user's rewards
     * @param user Address of the user
     */
    function _updateRewards(address user) internal {
        uint256 pending = earned(user);
        rewardDebt[user] = pending;
        lastStaked[user] = block.timestamp;
    }

    /**
     * @notice Calculates the rewards earned by a user
     * @param user Address of the user
     * @return Amount of rewards earned
     */
    function earned(address user) public view returns (uint256) {
        if (staked[user] == 0) return rewardDebt[user];
        uint256 timeElapsed = block.timestamp - lastStaked[user];
        uint256 reward = (staked[user] * aprBasisPoints * timeElapsed) / BPS_DIVISOR / SECONDS_IN_YEAR;
        return reward + rewardDebt[user];
    }

    /**
     * @notice Returns the number of tokens a user has staked
     * @param user Address of the user
     * @return Amount of tokens staked
     */
    function getStaked(address user) external view returns (uint256) {
        return staked[user];
    }

    /**
     * @notice Returns the current APR as a percentage
     * @return APR percentage (e.g., 25.00 for 25%)
     */
    function getAPR() external view returns (uint256) {
        return aprBasisPoints / 100;
    }
}

contracts/SoloMethodEngineV2.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "./interfaces/ISovranWealthFund.sol";

/**
 * @title SoloMethodEngineV2
 * @notice Enhanced staking system with 16-wallet structure and dynamic APR
 * @dev Combines staking, role-based wallet distribution, and adjustable reward rates
 */
contract SoloMethodEngineV2 is Ownable, AccessControl {
    // Token to stake
    IERC20 public stakingToken;

    // Wallet structure types
    enum WalletRole { BUYER, HOLDER, STAKER, LIQUIDITY, TRACKER }

    struct WalletInfo {
        WalletRole role;
        uint256 balance;
    }

    // 16-wallet structure per user
    mapping(address => WalletInfo[16]) public userWallets;

    // Staking tracking
    mapping(address => uint256) public stakedAmount;
    mapping(address => uint256) public lastRewardTime;
    mapping(address => uint256) public rewardDebt;

    // Role for APR management
    bytes32 public constant APR_MANAGER_ROLE = keccak256("APR_MANAGER_ROLE");

    // Dynamic APR settings
    uint256 public aprBasisPoints = 2500; // 25% APR (in basis points)
    uint256 public constant BPS_DIVISOR = 10000;
    uint256 public constant SECONDS_IN_YEAR = 31536000;
    uint256 public constant MIN_STAKE_AMOUNT = 50 * 1e18; // 50 SWF minimum

    // Events
    event Deposited(address indexed user, uint256 amount);
    event Withdrawn(address indexed user, uint256 amount);
    event Minted(address indexed user, uint256 reward);
    event APRUpdated(uint256 oldAPR, uint256 newAPR);

    /**
     * @notice Constructs the SoloMethodEngineV2 contract
     * @param _stakingTokenAddress Address of the token to stake
     */
    constructor(address _stakingTokenAddress) Ownable(msg.sender) {
        require(_stakingTokenAddress != address(0), "Invalid token address");
        stakingToken = IERC20(_stakingTokenAddress);

        // Grant admin role to deployer
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        // Grant APR manager role to deployer initially
        _grantRole(APR_MANAGER_ROLE, msg.sender);
    }

    /**
     * @notice Set a new APR value (in basis points) - callable by owner or APR manager
     * @param _newAprBps The new APR in basis points (100 = 1%)
     */
    function setAPR(uint256 _newAprBps) external {
        require(
            hasRole(APR_MANAGER_ROLE, msg.sender) || owner() == msg.sender,
            "Caller is not APR manager or owner"
        );
        require(_newAprBps <= 5000, "APR too high (max 50%)");
        uint256 oldApr = aprBasisPoints;
        aprBasisPoints = _newAprBps;
        emit APRUpdated(oldApr, _newAprBps);
    }

    /**
     * @notice Grant APR manager role to an address
     * @param account Address to grant the role to
     */
    function grantAPRManagerRole(address account) external onlyOwner {
        require(account != address(0), "Invalid address");
        _grantRole(APR_MANAGER_ROLE, account);
    }

    /**
     * @notice Revoke APR manager role from an address
     * @param account Address to revoke the role from
     */
    function revokeAPRManagerRole(address account) external onlyOwner {
        _revokeRole(APR_MANAGER_ROLE, account);
    }

    /**
     * @notice Stake tokens and distribute them across 16 wallets
     * @param amount The amount to stake
     */
    function deposit(uint256 amount) external {
        require(amount >= MIN_STAKE_AMOUNT, "Minimum 50 SWF required");
        require(stakingToken.transferFrom(msg.sender, address(this), amount), "Transfer failed");

        // Update rewards before changing stake
        _updateRewards(msg.sender);

        // Distribute the amount across 16 wallets evenly
        for (uint8 i = 0; i < 16; i++) {
            userWallets[msg.sender][i] = WalletInfo(WalletRole(i % 5), amount / 16);
        }

        stakedAmount[msg.sender] += amount;
        lastRewardTime[msg.sender] = block.timestamp;
        emit Deposited(msg.sender, amount);
    }

    /**
     * @notice Withdraw staked tokens
     * @param amount The amount to withdraw
     */
    function withdraw(uint256 amount) external {
        require(amount > 0, "Amount must be greater than 0");
        require(stakedAmount[msg.sender] >= amount, "Insufficient staked balance");

        // Update rewards before changing stake
        _updateRewards(msg.sender);

        // Update staked amount
        stakedAmount[msg.sender] -= amount;

        // Reset wallet distribution
        if (stakedAmount[msg.sender] > 0) {
            // Recalculate wallets with new amount
            uint256 amountPerWallet = stakedAmount[msg.sender] / 16;
            for (uint8 i = 0; i < 16; i++) {
                userWallets[msg.sender][i].balance = amountPerWallet;
            }
        } else {
            // Clear all wallets if fully withdrawn
            for (uint8 i = 0; i < 16; i++) {
                userWallets[msg.sender][i].balance = 0;
            }
        }

        // Transfer SWF tokens back to user
        require(stakingToken.transfer(msg.sender, amount), "Transfer failed");
        emit Withdrawn(msg.sender, amount);
    }

    /**
     * @notice Update user's reward debt for precise tracking
     * @param user The user address to update rewards for
     */
    function _updateRewards(address user) internal {
        uint256 pending = calculateRewards(user);
        rewardDebt[user] = pending;
        lastRewardTime[user] = block.timestamp;
    }

    /**
     * @notice Calculate earned rewards with continuous compounding
     * @param user The user address to calculate rewards for
     * @return The calculated reward amount
     */
    function calculateRewards(address user) public view returns (uint256) {
        if (stakedAmount[user] == 0 || lastRewardTime[user] == 0) {
            return rewardDebt[user];
        }

        uint256 timeElapsed = block.timestamp - lastRewardTime[user];

        // Calculate reward: staked * APR * (timeElapsed / SECONDS_IN_YEAR)
        uint256 reward = (stakedAmount[user] * aprBasisPoints * timeElapsed) / 
                        BPS_DIVISOR / SECONDS_IN_YEAR;

        return reward + rewardDebt[user];
    }

    /**
     * @notice Claim accumulated rewards
     */
    function claimRewards() public {
        _updateRewards(msg.sender);
        uint256 reward = rewardDebt[msg.sender];

        if (reward > 0) {
            rewardDebt[msg.sender] = 0;

            // Transfer rewards to user (requires contract to have minter role)
            ISovranWealthFund swfTokenMinter = ISovranWealthFund(address(stakingToken));
            swfTokenMinter.mint(msg.sender, reward);
            emit Minted(msg.sender, reward);
        }
    }

    /**
     * @notice Get the distribution of tokens across 16 wallets
     * @param user The user address to check wallet breakdown for
     * @return Array of WalletInfo structures
     */
    function getWalletBreakdown(address user) external view returns (WalletInfo[16] memory) {
        return userWallets[user];
    }

    /**
     * @notice Get total staked amount for a user
     * @param user The user address to check staked amount for
     * @return The total staked amount
     */
    function getTotalStaked(address user) external view returns (uint256) {
        return stakedAmount[user];
    }

    /**
     * @notice Get pending rewards for a user
     * @param user The user address to check pending rewards for
     * @return The pending reward amount
     */
    function getPendingRewards(address user) external view returns (uint256) {
        return calculateRewards(user);
    }

    /**
     * @notice Get current APR in basis points
     * @return The current APR in basis points
     */
    function getCurrentAPR() external view returns (uint256) {
        return aprBasisPoints;
    }

    /**
     * @notice Check if the specified address has staked tokens
     * @param user The user address to check
     * @return True if the user has staked tokens, false otherwise
     */
    function isStaker(address user) external view returns (bool) {
        return stakedAmount[user] > 0;
    }

    /**
     * @notice Emergency function to recover any tokens accidentally sent to this contract
     * @param token Address of the token to recover
     * @param amount Amount to recover
     */
    function recoverTokens(address token, uint256 amount) external onlyOwner {
        require(token != address(stakingToken), "Cannot recover staking token");
        require(IERC20(token).transfer(owner(), amount), "Token recovery failed");
    }

    /**
     * @notice Check if an address has APR manager role
     * @param account Address to check
     * @return True if the address has APR manager role
     */
    function isAPRManager(address account) external view returns (bool) {
        return hasRole(APR_MANAGER_ROLE, account);
    }

    /**
     * @notice Get the APR manager role identifier
     * @return The APR manager role bytes32 identifier
     */
    function getAPRManagerRole() external pure returns (bytes32) {
        return APR_MANAGER_ROLE;
    }

    /**
     * @notice Support interface detection
     * @param interfaceId Interface to check
     * @return True if interface is supported
     */
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

contracts/SovranID.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC721/ERC721.sol";
import "@openzeppelin/contracts/token/ERC721/extensions/ERC721URIStorage.sol";
import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./MoabiteConstitution.sol";

/**
 * @title SovranID
 * @dev NFT-based citizenship system for The Moabite Federation
 * Each SovranID represents a citizen with tribal metadata and governance rights
 */
contract SovranID is ERC721, ERC721URIStorage, AccessControl, ReentrancyGuard {

    // Role definitions
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant REGISTRAR_ROLE = keccak256("REGISTRAR_ROLE");

    // Tribal affiliation structure
    struct TribalInfo {
        string tribeName;         // Name of the tribe/clan
        string lineage;           // Ancestral lineage information
        string region;            // Geographic region
        uint256 joinDate;         // When citizen joined the tribe
        bool isTribalLeader;      // Leadership status
        string additionalData;    // Additional tribal metadata
    }

    // Citizen profile structure
    struct CitizenProfile {
        uint256 tokenId;          // SovranID token ID
        string sovereignName;     // Chosen sovereign name
        bytes32 biometricHash;    // Hash of biometric data (optional)
        string ipfsMetadata;      // IPFS hash of additional metadata
        uint256 issuanceDate;     // When the ID was issued
        uint256 expirationDate;   // ID expiration (0 for lifetime)
        bool isActive;            // Current status
        bool hasVotingRights;     // Constitutional voting rights
        TribalInfo tribal;        // Tribal affiliation data
    }

    // State variables
    MoabiteConstitution public constitution;
    uint256 private _tokenIdCounter;

    mapping(uint256 => CitizenProfile) public citizens;
    mapping(address => uint256) public addressToTokenId;
    mapping(string => bool) public sovereignNameTaken;
    mapping(string => uint256[]) public tribeMembers; // tribe name => token IDs

    uint256 public constant MAX_SUPPLY = 100000; // Maximum citizens
    bool public mintingPaused = false;

    // Events
    event SovranIDMinted(uint256 indexed tokenId, address indexed citizen, string sovereignName, string tribeName);
    event TribalInfoUpdated(uint256 indexed tokenId, string tribeName, bool isLeader);
    event VotingRightsGranted(uint256 indexed tokenId, bool granted);
    event CitizenshipRevoked(uint256 indexed tokenId, string reason);
    event BiometricHashUpdated(uint256 indexed tokenId, bytes32 newHash);

    modifier onlyConstitution() {
        require(msg.sender == address(constitution), "SovranID: Only constitution contract");
        _;
    }

    modifier onlyActiveCitizen(uint256 tokenId) {
        require(citizens[tokenId].isActive, "SovranID: Citizen not active");
        require(citizens[tokenId].expirationDate == 0 || block.timestamp <= citizens[tokenId].expirationDate, "SovranID: ID expired");
        _;
    }

    constructor(address _constitution) ERC721("SovranID - Moabite Federation Citizenship", "SOVRANID") {
        require(_constitution != address(0), "Invalid constitution address");
        constitution = MoabiteConstitution(_constitution);

        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(REGISTRAR_ROLE, msg.sender);

        // Start token IDs at 1
        _tokenIdCounter++;
    }

    /**
     * @dev Mint a new SovranID for a citizen
     */
    function mintSovranID(
        address to,
        string memory sovereignName,
        string memory tribeName,
        string memory lineage,
        string memory region,
        string memory ipfsMetadata,
        bytes32 biometricHash,
        bool hasVotingRights
    ) external onlyRole(MINTER_ROLE) nonReentrant returns (uint256) {
        require(!mintingPaused, "SovranID: Minting is paused");
        require(to != address(0), "SovranID: Cannot mint to zero address");
        require(addressToTokenId[to] == 0, "SovranID: Address already has ID");
        require(!sovereignNameTaken[sovereignName], "SovranID: Sovereign name taken");
        require(bytes(sovereignName).length > 0, "SovranID: Sovereign name required");
        require(bytes(tribeName).length > 0, "SovranID: Tribe name required");
        require(_tokenIdCounter <= MAX_SUPPLY, "SovranID: Max supply reached");

        uint256 tokenId = _tokenIdCounter;
        _tokenIdCounter++;

        // Create citizen profile
        citizens[tokenId] = CitizenProfile({
            tokenId: tokenId,
            sovereignName: sovereignName,
            biometricHash: biometricHash,
            ipfsMetadata: ipfsMetadata,
            issuanceDate: block.timestamp,
            expirationDate: 0, // Lifetime by default
            isActive: true,
            hasVotingRights: hasVotingRights,
            tribal: TribalInfo({
                tribeName: tribeName,
                lineage: lineage,
                region: region,
                joinDate: block.timestamp,
                isTribalLeader: false,
                additionalData: ""
            })
        });

        // Update mappings
        addressToTokenId[to] = tokenId;
        sovereignNameTaken[sovereignName] = true;
        tribeMembers[tribeName].push(tokenId);

        // Mint the NFT
        _safeMint(to, tokenId);
        _setTokenURI(tokenId, ipfsMetadata);

        // Grant citizenship in constitution contract
        if (hasVotingRights) {
            constitution.grantCitizenship(to);
        }

        emit SovranIDMinted(tokenId, to, sovereignName, tribeName);

        return tokenId;
    }

    /**
     * @dev Update tribal information
     */
    function updateTribalInfo(
        uint256 tokenId,
        string memory newTribeName,
        string memory newLineage,
        string memory newRegion,
        string memory additionalData
    ) external onlyRole(REGISTRAR_ROLE) onlyActiveCitizen(tokenId) {
        CitizenProfile storage citizen = citizens[tokenId];

        // Remove from old tribe if changing
        if (keccak256(bytes(citizen.tribal.tribeName)) != keccak256(bytes(newTribeName))) {
            _removeFromTribe(tokenId, citizen.tribal.tribeName);
            tribeMembers[newTribeName].push(tokenId);
        }

        citizen.tribal.tribeName = newTribeName;
        citizen.tribal.lineage = newLineage;
        citizen.tribal.region = newRegion;
        citizen.tribal.additionalData = additionalData;

        emit TribalInfoUpdated(tokenId, newTribeName, citizen.tribal.isTribalLeader);
    }

    /**
     * @dev Grant or revoke tribal leadership
     */
    function setTribalLeadership(uint256 tokenId, bool isLeader) external onlyRole(REGISTRAR_ROLE) onlyActiveCitizen(tokenId) {
        CitizenProfile storage citizen = citizens[tokenId];
        citizen.tribal.isTribalLeader = isLeader;

        // Grant tribal leader role in constitution if needed
        if (isLeader) {
            constitution.grantRole(constitution.TRIBAL_LEADER_ROLE(), ownerOf(tokenId));
        }

        emit TribalInfoUpdated(tokenId, citizen.tribal.tribeName, isLeader);
    }

    /**
     * @dev Update biometric hash
     */
    function updateBiometricHash(uint256 tokenId, bytes32 newHash) external {
        require(ownerOf(tokenId) == msg.sender || hasRole(REGISTRAR_ROLE, msg.sender), "SovranID: Not authorized");
        require(citizens[tokenId].isActive, "SovranID: Citizen not active");

        citizens[tokenId].biometricHash = newHash;
        emit BiometricHashUpdated(tokenId, newHash);
    }

    /**
     * @dev Grant or revoke voting rights
     */
    function setVotingRights(uint256 tokenId, bool hasRights) external onlyRole(REGISTRAR_ROLE) onlyActiveCitizen(tokenId) {
        CitizenProfile storage citizen = citizens[tokenId];
        citizen.hasVotingRights = hasRights;

        address citizenAddress = ownerOf(tokenId);
        if (hasRights) {
            constitution.grantCitizenship(citizenAddress);
        } else {
            constitution.revokeCitizenship(citizenAddress);
        }

        emit VotingRightsGranted(tokenId, hasRights);
    }

    /**
     * @dev Revoke citizenship
     */
    function revokeCitizenship(uint256 tokenId, string memory reason) external onlyRole(REGISTRAR_ROLE) {
        require(_ownerOf(tokenId) != address(0), "SovranID: Token does not exist");

        CitizenProfile storage citizen = citizens[tokenId];
        citizen.isActive = false;
        citizen.hasVotingRights = false;

        // Remove from constitution
        address citizenAddress = ownerOf(tokenId);
        constitution.revokeCitizenship(citizenAddress);

        // Remove from tribe
        _removeFromTribe(tokenId, citizen.tribal.tribeName);

        emit CitizenshipRevoked(tokenId, reason);
    }

    /**
     * @dev Get citizen profile
     */
    function getCitizenProfile(uint256 tokenId) external view returns (
        string memory sovereignName,
        string memory tribeName,
        string memory lineage,
        string memory region,
        uint256 issuanceDate,
        bool isActive,
        bool hasVotingRights,
        bool isTribalLeader
    ) {
        require(_ownerOf(tokenId) != address(0), "SovranID: Token does not exist");
        CitizenProfile storage citizen = citizens[tokenId];

        return (
            citizen.sovereignName,
            citizen.tribal.tribeName,
            citizen.tribal.lineage,
            citizen.tribal.region,
            citizen.issuanceDate,
            citizen.isActive,
            citizen.hasVotingRights,
            citizen.tribal.isTribalLeader
        );
    }

    /**
     * @dev Get tribe members
     */
    function getTribeMembers(string memory tribeName) external view returns (uint256[] memory) {
        return tribeMembers[tribeName];
    }

    /**
     * @dev Check if address is a citizen
     */
    function isCitizen(address account) external view returns (bool) {
        uint256 tokenId = addressToTokenId[account];
        if (tokenId == 0) return false;

        CitizenProfile storage citizen = citizens[tokenId];
        return citizen.isActive && (citizen.expirationDate == 0 || block.timestamp <= citizen.expirationDate);
    }

    /**
     * @dev Verify biometric hash
     */
    function verifyBiometric(uint256 tokenId, bytes32 hash) external view returns (bool) {
        require(_ownerOf(tokenId) != address(0), "SovranID: Token does not exist");
        return citizens[tokenId].biometricHash == hash && citizens[tokenId].isActive;
    }

    /**
     * @dev Remove token from tribe members array
     */
    function _removeFromTribe(uint256 tokenId, string memory tribeName) internal {
        uint256[] storage members = tribeMembers[tribeName];
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == tokenId) {
                members[i] = members[members.length - 1];
                members.pop();
                break;
            }
        }
    }

    /**
     * @dev Pause/unpause minting
     */
    function setMintingPaused(bool paused) external onlyRole(DEFAULT_ADMIN_ROLE) {
        mintingPaused = paused;
    }

    /**
     * @dev Override transfer to update constitution citizenship
     * NOTE: OpenZeppelin v5 removed _beforeTokenTransfer hook, using _update instead
     */
    function _update(address to, uint256 tokenId, address auth) internal virtual override returns (address) {
        address from = _ownerOf(tokenId);
        address previousOwner = super._update(to, tokenId, auth);

        if (from != address(0) && to != address(0)) {
            // Update address mapping
            addressToTokenId[from] = 0;
            addressToTokenId[to] = tokenId;

            // Update constitution citizenship
            CitizenProfile storage citizen = citizens[tokenId];
            if (citizen.hasVotingRights && citizen.isActive) {
                constitution.revokeCitizenship(from);
                constitution.grantCitizenship(to);
            }
        }

        return previousOwner;
    }

    // OpenZeppelin v5: _burn doesn't need override since we're not changing behavior
    // The ERC721URIStorage extension handles burning automatically through inheritance

    function tokenURI(uint256 tokenId) public view override(ERC721, ERC721URIStorage) returns (string memory) {
        return super.tokenURI(tokenId);
    }

    function supportsInterface(bytes4 interfaceId) public view override(ERC721, ERC721URIStorage, AccessControl) returns (bool) {
        return super.supportsInterface(interfaceId);
    }
}

